(function(){/* ===================================================================
   i18nlifetools-c — Life Tools batch A (14-tool expansion, tools 1-4):
   group headers + framing line + Perception, The projector,
   Challenges are opportunities, Clear identity clear goal.
   All 15 non-English languages. Merge-if-missing into CF_UI_MAP.
   =================================================================== */(function(){if(typeof CF_UI_MAP==='undefined')return;var M={"Ways of seeing":{es:"Maneras de ver",ca:"Maneres de veure",fr:"Manières de voir",de:"Sichtweisen",it:"Modi di vedere",pt:"Maneiras de ver",zh:"看待事物的方式",ja:"ものの見方",ko:"바라보는 방법",hi:"देखने के तरीक़े",id:"Cara memandang",tr:"Görme biçimleri",ru:"Способы видеть",vi:"Những cách nhìn",ar:"طرق للرؤية"},"Knowing yourself":{es:"Conocerte",ca:"Conèixer-te",fr:"Se connaître",de:"Sich selbst kennen",it:"Conoscersi",pt:"Conhecer-te",zh:"认识自己",ja:"自分を知る",ko:"나를 알기",hi:"खुद को जानना",id:"Mengenal diri",tr:"Kendini tanımak",ru:"Знать себя",vi:"Hiểu chính mình",ar:"معرفة نفسك"},"Living the day":{es:"Vivir el día",ca:"Viure el dia",fr:"Vivre la journée",de:"Den Tag leben",it:"Vivere la giornata",pt:"Viver o dia",zh:"过好这一天",ja:"一日を生きる",ko:"하루를 살아가기",hi:"दिन को जीना",id:"Menjalani hari",tr:"Günü yaşamak",ru:"Проживать день",vi:"Sống trọn ngày",ar:"عيش اليوم"},"Growing over time":{es:"Crecer con el tiempo",ca:"Créixer amb el temps",fr:"Grandir avec le temps",de:"Mit der Zeit wachsen",it:"Crescere nel tempo",pt:"Crescer com o tempo",zh:"随时间成长",ja:"時間をかけて育つ",ko:"시간과 함께 자라기",hi:"समय के साथ बढ़ना",id:"Bertumbuh seiring waktu",tr:"Zamanla büyümek",ru:"Расти со временем",vi:"Lớn lên theo thời gian",ar:"النموّ مع الوقت"},"Everything here is personal mindset practice. It sits beside your healthcare, never in place of it.":{es:"Todo lo de aquí es práctica personal de mentalidad. Acompaña a tu atención médica, nunca la sustituye.",ca:"Tot el que hi ha aquí és pràctica personal de mentalitat. Acompanya la teva atenció mèdica, mai no la substitueix.",fr:"Tout ici relève d'une pratique personnelle d'état d'esprit. Cela accompagne vos soins, sans jamais les remplacer.",de:"Alles hier ist persönliche Mentalitätsübung. Es begleitet deine medizinische Versorgung und ersetzt sie nie.",it:"Tutto ciò che trovi qui è pratica personale di mentalità. Affianca le tue cure, non le sostituisce mai.",pt:"Tudo aqui é prática pessoal de mentalidade. Anda ao lado dos teus cuidados de saúde, nunca no lugar deles.",zh:"这里的一切都是个人心态练习。它伴随你的医疗照护，绝不取代它。",ja:"ここにあるのはすべて、心の持ち方のセルフプラクティスです。医療に寄り添うものであり、代わりになるものではありません。",ko:"여기 있는 모든 것은 개인적인 마음가짐 연습입니다. 의료를 대신하는 것이 아니라 곁에 함께합니다.",hi:"यहाँ जो कुछ है वह व्यक्तिगत मानसिकता अभ्यास है। यह आपकी चिकित्सा देखभाल के साथ चलता है, कभी उसकी जगह नहीं लेता।",id:"Semua yang ada di sini adalah latihan pola pikir pribadi. Ia mendampingi perawatan kesehatanmu, tidak pernah menggantikannya.",tr:"Buradaki her şey kişisel bir zihniyet pratiğidir. Sağlık bakımının yanında durur, asla onun yerine geçmez.",ru:"Всё здесь — личная практика мышления. Она идёт рядом с вашим лечением и никогда его не заменяет.",vi:"Mọi thứ ở đây là thực hành tư duy cá nhân. Nó đồng hành cùng việc chăm sóc y tế của bạn, không bao giờ thay thế.",ar:"كل ما هنا ممارسة شخصية لطريقة التفكير. إنها ترافق رعايتك الصحية ولا تحلّ محلّها أبدًا."},"Perception":{es:"Percepción",ca:"Percepció",fr:"Perception",de:"Wahrnehmung",it:"Percezione",pt:"Perceção",zh:"感知",ja:"知覚",ko:"지각",hi:"बोध",id:"Persepsi",tr:"Algı",ru:"Восприятие",vi:"Nhận thức",ar:"الإدراك"},"What you notice is a selection — and selections can widen.":{es:"Lo que notas es una selección, y las selecciones pueden ampliarse.",ca:"El que notes és una selecció, i les seleccions es poden ampliar.",fr:"Ce que vous remarquez est une sélection — et une sélection peut s'élargir.",de:"Was du bemerkst, ist eine Auswahl — und Auswahlen können sich weiten.",it:"Ciò che noti è una selezione, e le selezioni possono allargarsi.",pt:"O que notas é uma seleção — e as seleções podem alargar-se.",zh:"你注意到的只是一部分——而这部分可以变宽。",ja:"目に入るものは選ばれた一部。その選択は広げられます。",ko:"당신이 알아차리는 것은 선택된 일부 — 그 선택은 넓어질 수 있습니다.",hi:"आप जो देखते हैं वह एक चयन है — और चयन बढ़ाया जा सकता है।",id:"Yang kamu sadari hanyalah pilihan — dan pilihan bisa diperluas.",tr:"Fark ettiklerin bir seçkidir — ve seçkiler genişleyebilir.",ru:"То, что вы замечаете, — это выборка, а выборку можно расширить.",vi:"Điều bạn chú ý chỉ là một phần được chọn — và phần đó có thể mở rộng.",ar:"ما تلاحظه هو انتقاء — والانتقاء يمكن أن يتّسع."},"Your attention can't hold everything, so it selects — and it tends to select whatever shouts loudest. That isn't a flaw; it's how attention works. But it means every day contains more than the version of it you noticed. On a day when your body sets the pace, this is worth remembering: the loudest thing in the room is not the only thing in the room.":{es:"Tu atención no puede abarcarlo todo, así que selecciona — y tiende a seleccionar lo que más grita. No es un defecto; así funciona la atención. Pero significa que cada día contiene más que la versión que notaste. Un día en que tu cuerpo marca el ritmo, conviene recordarlo: lo que más suena en la habitación no es lo único que hay en la habitación.",ca:"La teva atenció no ho pot abastar tot, així que selecciona — i tendeix a seleccionar el que més crida. No és un defecte; així funciona l'atenció. Però vol dir que cada dia conté més que la versió que en vas notar. Un dia en què el teu cos marca el ritme, val la pena recordar-ho: el que més sona a l'habitació no és l'únic que hi ha a l'habitació.",fr:"Votre attention ne peut pas tout contenir, alors elle sélectionne — et elle tend à choisir ce qui crie le plus fort. Ce n'est pas un défaut ; c'est ainsi que l'attention fonctionne. Mais cela signifie que chaque journée contient plus que la version que vous en avez remarquée. Un jour où votre corps donne le rythme, cela vaut la peine de s'en souvenir : la chose la plus bruyante de la pièce n'est pas la seule chose dans la pièce.",de:"Deine Aufmerksamkeit kann nicht alles fassen, also wählt sie aus — und sie wählt meist, was am lautesten ruft. Das ist kein Fehler; so arbeitet Aufmerksamkeit. Aber es bedeutet: Jeder Tag enthält mehr als die Version, die du bemerkt hast. An einem Tag, an dem dein Körper das Tempo vorgibt, lohnt es sich, daran zu denken: Das Lauteste im Raum ist nicht das Einzige im Raum.",it:"La tua attenzione non può contenere tutto, quindi seleziona — e tende a selezionare ciò che grida più forte. Non è un difetto; è così che funziona l'attenzione. Ma significa che ogni giornata contiene più della versione che hai notato. In un giorno in cui il corpo detta il ritmo, vale la pena ricordarlo: la cosa più rumorosa nella stanza non è l'unica cosa nella stanza.",pt:"A tua atenção não consegue abarcar tudo, por isso seleciona — e tende a selecionar o que grita mais alto. Não é um defeito; é assim que a atenção funciona. Mas significa que cada dia contém mais do que a versão que notaste. Num dia em que o corpo dita o ritmo, vale a pena lembrar: a coisa mais barulhenta na sala não é a única coisa na sala.",zh:"注意力装不下所有东西，所以它会挑选——而它往往挑最响亮的。这不是缺陷，注意力本来就这样工作。但这意味着，每一天都比你注意到的版本更丰富。在身体做主的日子里，值得记住：屋里最响的那件事，不是屋里唯一的事。",ja:"注意はすべてを抱えられないので、選びます。しかも、いちばん大きな声で叫ぶものを選びがちです。それは欠点ではなく、注意の仕組みです。ただ、つまり一日には、あなたが気づいた版よりも多くのことが含まれているということ。体がペースを決める日ほど、思い出す価値があります。部屋でいちばん騒がしいものが、部屋にある唯一のものではありません。",ko:"주의력은 모든 것을 담을 수 없어 선택합니다 — 그리고 가장 크게 외치는 것을 고르는 경향이 있죠. 결함이 아니라 주의력이 원래 그렇게 작동합니다. 하지만 그 말은, 하루하루가 당신이 알아차린 버전보다 더 많은 것을 담고 있다는 뜻입니다. 몸이 속도를 정하는 날일수록 기억할 가치가 있습니다. 방에서 가장 시끄러운 것이 방에 있는 유일한 것은 아닙니다.",hi:"आपका ध्यान सब कुछ नहीं समेट सकता, इसलिए वह चुनता है — और अक्सर वही चुनता है जो सबसे ज़ोर से चिल्लाता है। यह कोई कमी नहीं; ध्यान ऐसे ही काम करता है। पर इसका मतलब है कि हर दिन में उससे ज़्यादा होता है जितना आपने देखा। जिस दिन शरीर रफ़्तार तय करे, यह याद रखने लायक़ है: कमरे में सबसे ऊँची आवाज़ वाली चीज़ कमरे की इकलौती चीज़ नहीं है।",id:"Perhatianmu tak bisa menampung semuanya, jadi ia memilih — dan cenderung memilih yang berteriak paling keras. Itu bukan cacat; begitulah cara kerja perhatian. Tapi artinya, setiap hari berisi lebih banyak daripada versi yang kamu sadari. Di hari ketika tubuh menentukan irama, ini layak diingat: hal paling ribut di ruangan bukanlah satu-satunya hal di ruangan.",tr:"Dikkatin her şeyi tutamaz, bu yüzden seçer — ve genellikle en yüksek sesle bağıranı seçer. Bu bir kusur değil; dikkat böyle çalışır. Ama şu anlama gelir: Her gün, senin fark ettiğin halinden fazlasını içerir. Bedenin tempoyu belirlediği bir günde şunu hatırlamak iyi gelir: Odadaki en gürültülü şey, odadaki tek şey değildir.",ru:"Внимание не может вместить всё, поэтому оно выбирает — и обычно выбирает то, что кричит громче всех. Это не изъян; так внимание устроено. Но это значит, что каждый день содержит больше, чем та версия, которую вы заметили. В день, когда темп задаёт тело, об этом стоит помнить: самое громкое в комнате — не единственное, что в ней есть.",vi:"Sự chú ý không thể ôm hết mọi thứ, nên nó chọn lọc — và thường chọn thứ la to nhất. Đó không phải khiếm khuyết; chú ý vốn hoạt động như vậy. Nhưng điều đó nghĩa là mỗi ngày chứa nhiều hơn phiên bản bạn đã nhận ra. Vào ngày cơ thể quyết định nhịp độ, điều này đáng nhớ: thứ ồn ào nhất trong phòng không phải là thứ duy nhất trong phòng.",ar:"انتباهك لا يتّسع لكل شيء، لذا فهو ينتقي — ويميل إلى انتقاء الأعلى صوتًا. ليست هذه علّة؛ فهكذا يعمل الانتباه. لكن هذا يعني أن كل يوم يحوي أكثر من النسخة التي لاحظتها. وفي يومٍ يفرض فيه جسدك الإيقاع، يجدر بك أن تتذكّر: أعلى الأشياء صوتًا في الغرفة ليس الشيء الوحيد في الغرفة."},"The quiet inventory":{es:"El inventario silencioso",ca:"L'inventari silenciós",fr:"L'inventaire silencieux",de:"Die stille Bestandsaufnahme",it:"L'inventario silenzioso",pt:"O inventário silencioso",zh:"安静的清单",ja:"静かな棚卸し",ko:"조용한 목록 만들기",hi:"ख़ामोश सूची",id:"Inventaris yang tenang",tr:"Sessiz sayım",ru:"Тихая опись",vi:"Bản kiểm kê lặng lẽ",ar:"الجرد الهادئ"},"Without moving from where you are, name the three things that have taken most of your attention today.":{es:"Sin moverte de donde estás, nombra las tres cosas que más atención te han llevado hoy.",ca:"Sense moure't d'on ets, anomena les tres coses que més atenció t'han pres avui.",fr:"Sans bouger d'où vous êtes, nommez les trois choses qui ont pris le plus de votre attention aujourd'hui.",de:"Ohne dich vom Fleck zu rühren: Nenne die drei Dinge, die heute die meiste Aufmerksamkeit bekommen haben.",it:"Senza muoverti da dove sei, nomina le tre cose che oggi hanno preso più attenzione.",pt:"Sem saíres de onde estás, nomeia as três coisas que hoje levaram mais da tua atenção.",zh:"不用挪动位置，说出今天最占据你注意力的三件事。",ja:"その場から動かずに、今日いちばん注意を占めた三つのことを挙げます。",ko:"지금 있는 자리에서, 오늘 주의를 가장 많이 가져간 세 가지를 떠올려 봅니다.",hi:"जहाँ हैं वहीं से, आज सबसे ज़्यादा ध्यान खींचने वाली तीन चीज़ें गिनाएँ।",id:"Tanpa beranjak dari tempatmu, sebutkan tiga hal yang paling menyita perhatianmu hari ini.",tr:"Olduğun yerden kalkmadan, bugün dikkatini en çok alan üç şeyi say.",ru:"Не вставая с места, назовите три вещи, которые сегодня заняли больше всего вашего внимания.",vi:"Không cần rời khỏi chỗ, hãy kể ra ba điều chiếm nhiều sự chú ý của bạn nhất hôm nay.",ar:"من دون أن تتحرك من مكانك، سمِّ الأشياء الثلاثة التي أخذت معظم انتباهك اليوم."},"Now look for three quieter things that were also true: a warm drink, a message, ten calm minutes.":{es:"Ahora busca tres cosas más silenciosas que también fueron verdad: una bebida caliente, un mensaje, diez minutos de calma.",ca:"Ara busca tres coses més silencioses que també van ser veritat: una beguda calenta, un missatge, deu minuts de calma.",fr:"Cherchez maintenant trois choses plus discrètes qui étaient vraies aussi : une boisson chaude, un message, dix minutes de calme.",de:"Suche nun drei leisere Dinge, die auch wahr waren: ein warmes Getränk, eine Nachricht, zehn ruhige Minuten.",it:"Ora cerca tre cose più silenziose che erano vere anche loro: una bevanda calda, un messaggio, dieci minuti di calma.",pt:"Agora procura três coisas mais silenciosas que também foram verdade: uma bebida quente, uma mensagem, dez minutos de calma.",zh:"再找出三件也同样真实、却更安静的事：一杯热饮、一条消息、十分钟的平静。",ja:"次に、同じく本当にあった、もっと静かなことを三つ探します。温かい飲み物、届いたメッセージ、静かな十分間。",ko:"이제 똑같이 사실이었던 더 조용한 세 가지를 찾아봅니다. 따뜻한 음료, 메시지 하나, 고요했던 십 분.",hi:"अब तीन शांत चीज़ें खोजें जो उतनी ही सच थीं: एक गर्म पेय, कोई संदेश, दस सुकून भरे मिनट।",id:"Sekarang cari tiga hal yang lebih sunyi namun juga nyata: minuman hangat, sebuah pesan, sepuluh menit yang tenang.",tr:"Şimdi yine gerçek olan üç sessiz şey bul: sıcak bir içecek, bir mesaj, on sakin dakika.",ru:"Теперь найдите три более тихие вещи, которые тоже были правдой: тёплый напиток, сообщение, десять спокойных минут.",vi:"Giờ hãy tìm ba điều lặng lẽ hơn nhưng cũng có thật: một thức uống ấm, một tin nhắn, mười phút yên bình.",ar:"الآن ابحث عن ثلاثة أشياء أهدأ كانت حقيقية أيضًا: مشروب دافئ، رسالة، عشر دقائق من الهدوء."},"Hold both lists side by side. Neither one alone is 'the truth' — the day held both.":{es:"Pon las dos listas una junto a otra. Ninguna es por sí sola 'la verdad': el día contuvo ambas.",ca:"Posa les dues llistes una al costat de l'altra. Cap no és per si sola 'la veritat': el dia va contenir totes dues.",fr:"Placez les deux listes côte à côte. Aucune n'est à elle seule « la vérité » — la journée contenait les deux.",de:"Lege beide Listen nebeneinander. Keine ist allein 'die Wahrheit' — der Tag enthielt beide.",it:"Metti le due liste una accanto all'altra. Nessuna da sola è 'la verità': la giornata le conteneva entrambe.",pt:"Põe as duas listas lado a lado. Nenhuma sozinha é 'a verdade' — o dia continha ambas.",zh:"把两份清单放在一起看。哪一份都不是唯一的“真相”——这一天同时装着两者。",ja:"二つのリストを並べて眺めます。どちらか一方だけが「真実」ではありません。一日は両方を含んでいました。",ko:"두 목록을 나란히 놓아 봅니다. 어느 한쪽만이 '진실'은 아닙니다 — 하루는 둘 다 품고 있었습니다.",hi:"दोनों सूचियाँ साथ रखें। अकेली कोई भी 'सच' नहीं है — दिन में दोनों समाई थीं।",id:"Letakkan kedua daftar berdampingan. Tak satu pun yang sendirian adalah 'kebenaran' — hari itu memuat keduanya.",tr:"İki listeyi yan yana koy. Hiçbiri tek başına 'gerçek' değil — gün ikisini de içeriyordu.",ru:"Положите оба списка рядом. Ни один из них сам по себе не «правда» — день вмещал оба.",vi:"Đặt hai danh sách cạnh nhau. Không danh sách nào một mình là 'sự thật' — ngày hôm đó chứa cả hai.",ar:"ضع القائمتين جنبًا إلى جنب. لا واحدة منهما وحدها هي 'الحقيقة' — فاليوم حمل كلتيهما."},"Tomorrow, try to catch one quiet thing while it is happening. That's the whole skill, practised once.":{es:"Mañana, intenta cazar una cosa silenciosa mientras sucede. Esa es toda la habilidad, practicada una vez.",ca:"Demà, intenta caçar una cosa silenciosa mentre passa. Aquesta és tota l'habilitat, practicada un cop.",fr:"Demain, essayez d'attraper une chose discrète pendant qu'elle se produit. C'est toute la compétence, pratiquée une fois.",de:"Versuche morgen, eine leise Sache zu erwischen, während sie geschieht. Das ist die ganze Fähigkeit, einmal geübt.",it:"Domani, prova a cogliere una cosa silenziosa mentre accade. È tutta qui l'abilità, praticata una volta.",pt:"Amanhã, tenta apanhar uma coisa silenciosa enquanto acontece. É essa toda a competência, praticada uma vez.",zh:"明天，试着在一件安静的小事发生时当场捕捉它。这就是全部技巧，练一次就算数。",ja:"明日は、静かなことが起きているその瞬間に一つ気づいてみます。それがこの技のすべて。一回で十分です。",ko:"내일은 조용한 일 하나를 일어나는 순간에 붙잡아 보세요. 그것이 이 기술의 전부이고, 한 번이면 연습이 됩니다.",hi:"कल, कोई शांत चीज़ घटते समय ही पकड़ने की कोशिश करें। बस यही पूरा हुनर है, एक बार का अभ्यास।",id:"Besok, coba tangkap satu hal sunyi saat ia sedang terjadi. Itulah seluruh keterampilannya, dilatih sekali.",tr:"Yarın, sessiz bir şeyi olurken yakalamayı dene. Bütün beceri bu; bir kez çalışmak yeter.",ru:"Завтра попробуйте поймать одну тихую вещь, пока она происходит. В этом всё умение — один раз за день.",vi:"Ngày mai, thử bắt lấy một điều lặng lẽ ngay khi nó đang diễn ra. Đó là toàn bộ kỹ năng, luyện một lần là đủ.",ar:"غدًا، حاول أن تلتقط شيئًا هادئًا أثناء حدوثه. هذه هي المهارة كلها، تُمارَس مرة واحدة."},"The projector":{es:"El proyector",ca:"El projector",fr:"Le projecteur",de:"Der Projektor",it:"Il proiettore",pt:"O projetor",zh:"放映机",ja:"映写機",ko:"영사기",hi:"प्रोजेक्टर",id:"Proyektor",tr:"Projektör",ru:"Проектор",vi:"Máy chiếu",ar:"جهاز العرض"},"The mind is a projector of reality":{es:"La mente es un proyector de realidad",ca:"La ment és un projector de realitat",fr:"L'esprit est un projecteur de réalité",de:"Der Geist ist ein Projektor der Wirklichkeit",it:"La mente è un proiettore di realtà",pt:"A mente é um projetor de realidade",zh:"心是现实的放映机",ja:"心は現実の映写機",ko:"마음은 현실의 영사기",hi:"मन असलियत का प्रोजेक्टर है",id:"Pikiran adalah proyektor realitas",tr:"Zihin, gerçekliğin projektörüdür",ru:"Ум — проектор реальности",vi:"Tâm trí là chiếc máy chiếu thực tại",ar:"العقل جهاز عرضٍ للواقع"},"Your mind adds a caption to what it sees. You can learn to spot it.":{es:"Tu mente añade un pie de foto a lo que ve. Puedes aprender a detectarlo.",ca:"La teva ment afegeix un peu de foto al que veu. Pots aprendre a detectar-lo.",fr:"Votre esprit ajoute une légende à ce qu'il voit. Vous pouvez apprendre à la repérer.",de:"Dein Geist fügt dem, was er sieht, eine Bildunterschrift hinzu. Du kannst lernen, sie zu erkennen.",it:"La tua mente aggiunge una didascalia a ciò che vede. Puoi imparare a notarla.",pt:"A tua mente acrescenta uma legenda ao que vê. Podes aprender a notá-la.",zh:"你的心会给看到的东西配上说明文字。你可以学着认出它。",ja:"心は見たものに説明文をつけます。それに気づく練習ができます。",ko:"마음은 보이는 것에 설명을 덧붙입니다. 그것을 알아차리는 법은 배울 수 있습니다.",hi:"आपका मन जो देखता है उस पर एक कैप्शन जोड़ देता है। इसे पहचानना सीखा जा सकता है।",id:"Pikiranmu menambahkan keterangan pada apa yang dilihatnya. Kamu bisa belajar mengenalinya.",tr:"Zihnin gördüğü şeye bir altyazı ekler. Bunu fark etmeyi öğrenebilirsin.",ru:"Ум добавляет подпись к тому, что видит. Можно научиться её замечать.",vi:"Tâm trí gắn thêm chú thích vào điều nó thấy. Bạn có thể học cách nhận ra nó.",ar:"عقلك يضيف تعليقًا على ما يراه. ويمكنك أن تتعلّم رصده."},"'The mind is a projector' is a way of looking — a metaphor, not a mechanism. Between the world and you, the mind adds a layer: memories, moods, predictions. A slow morning can arrive already captioned 'a lost day' before it has had the chance to be anything. Spotting the projection doesn't change what's real, and it isn't supposed to. It simply reminds you that the caption came from the projector — and captions, unlike facts, can be rewritten.":{es:"'La mente es un proyector' es una forma de mirar: una metáfora, no un mecanismo. Entre el mundo y tú, la mente añade una capa: recuerdos, estados de ánimo, predicciones. Una mañana lenta puede llegar ya rotulada como 'un día perdido' antes de haber tenido ocasión de ser nada. Detectar la proyección no cambia lo que es real, ni pretende hacerlo. Solo te recuerda que el rótulo salió del proyector — y los rótulos, a diferencia de los hechos, pueden reescribirse.",ca:"'La ment és un projector' és una manera de mirar: una metàfora, no un mecanisme. Entre el món i tu, la ment afegeix una capa: records, estats d'ànim, prediccions. Un matí lent pot arribar ja retolat com 'un dia perdut' abans d'haver tingut ocasió de ser res. Detectar la projecció no canvia el que és real, ni ho pretén. Només et recorda que el rètol va sortir del projector — i els rètols, a diferència dels fets, es poden reescriure.",fr:"« L'esprit est un projecteur » est une manière de regarder — une métaphore, pas un mécanisme. Entre le monde et vous, l'esprit ajoute une couche : souvenirs, humeurs, prédictions. Un matin lent peut arriver déjà légendé « journée perdue » avant d'avoir eu la chance d'être quoi que ce soit. Repérer la projection ne change pas ce qui est réel, et ce n'est pas le but. Cela vous rappelle simplement que la légende vient du projecteur — et les légendes, contrairement aux faits, peuvent être réécrites.",de:"'Der Geist ist ein Projektor' ist eine Sichtweise — eine Metapher, kein Mechanismus. Zwischen die Welt und dich legt der Geist eine Schicht: Erinnerungen, Stimmungen, Vorhersagen. Ein langsamer Morgen kann schon mit der Unterschrift 'ein verlorener Tag' ankommen, bevor er die Chance hatte, irgendetwas zu sein. Die Projektion zu erkennen ändert nicht, was real ist — und das soll es auch nicht. Es erinnert dich nur daran, dass die Unterschrift vom Projektor stammt — und Unterschriften lassen sich, anders als Tatsachen, neu schreiben.",it:"'La mente è un proiettore' è un modo di guardare: una metafora, non un meccanismo. Tra il mondo e te, la mente aggiunge uno strato: ricordi, umori, previsioni. Una mattina lenta può arrivare già con la didascalia 'una giornata persa' prima di aver avuto la possibilità di essere qualcosa. Notare la proiezione non cambia ciò che è reale, e non è questo lo scopo. Ti ricorda soltanto che la didascalia veniva dal proiettore — e le didascalie, a differenza dei fatti, si possono riscrivere.",pt:"'A mente é um projetor' é uma forma de olhar — uma metáfora, não um mecanismo. Entre o mundo e ti, a mente acrescenta uma camada: memórias, humores, previsões. Uma manhã lenta pode chegar já legendada como 'um dia perdido' antes de ter tido a oportunidade de ser alguma coisa. Notar a projeção não muda o que é real, nem é suposto mudar. Apenas te lembra que a legenda veio do projetor — e as legendas, ao contrário dos factos, podem ser reescritas.",zh:"“心是放映机”是一种看法——是比喻，不是机制。在世界和你之间，心加了一层：记忆、心情、预测。一个缓慢的早晨，可能还没来得及成为任何东西，就已经被配上“荒废的一天”的字幕。认出这层放映不会改变真实，也不需要改变。它只是提醒你：字幕来自放映机——而字幕不同于事实，是可以重写的。",ja:"「心は映写機」というのはものの見方であって、仕組みの話ではありません。世界とあなたのあいだに、心は一枚の層を挟みます。記憶、気分、予測。ゆっくりした朝は、何かになる前から「失われた一日」という字幕つきで届くことがあります。映写に気づいても現実は変わりませんし、変えるためのものでもありません。ただ、字幕が映写機から来たことを思い出させてくれるだけ。そして字幕は、事実と違って、書き直せます。",ko:"'마음은 영사기'라는 말은 하나의 보는 방식입니다 — 은유이지, 작동 원리가 아닙니다. 세상과 당신 사이에 마음은 한 겹을 덧댑니다. 기억, 기분, 예측. 느린 아침은 무언가가 되어 보기도 전에 '망친 하루'라는 자막을 달고 도착하기도 합니다. 그 영사를 알아차린다고 현실이 바뀌지는 않고, 바꾸려는 것도 아닙니다. 다만 자막이 영사기에서 나왔다는 걸 일깨워 줄 뿐입니다 — 그리고 자막은 사실과 달리 다시 쓸 수 있습니다.",hi:"'मन एक प्रोजेक्टर है' देखने का एक ढंग है — रूपक, कोई तंत्र नहीं। दुनिया और आपके बीच मन एक परत जोड़ता है: यादें, मनोदशाएँ, अनुमान। एक धीमी सुबह कुछ बन पाने से पहले ही 'बर्बाद दिन' का कैप्शन लिए आ सकती है। इस प्रोजेक्शन को पहचानने से असलियत नहीं बदलती, और बदलनी भी नहीं है। यह बस याद दिलाता है कि कैप्शन प्रोजेक्टर से आया था — और कैप्शन, तथ्यों के उलट, दोबारा लिखे जा सकते हैं।",id:"'Pikiran adalah proyektor' adalah cara memandang — metafora, bukan mekanisme. Di antara dunia dan dirimu, pikiran menambahkan satu lapisan: kenangan, suasana hati, prediksi. Pagi yang lambat bisa tiba sudah berjudul 'hari yang hilang' sebelum sempat menjadi apa pun. Mengenali proyeksi itu tidak mengubah yang nyata, dan memang bukan itu tujuannya. Ia hanya mengingatkan bahwa judul itu datang dari proyektor — dan judul, tak seperti fakta, bisa ditulis ulang.",tr:"'Zihin bir projektördür' bir bakış biçimidir — bir metafor, bir mekanizma değil. Dünya ile senin arana zihin bir katman ekler: anılar, ruh halleri, tahminler. Yavaş bir sabah, daha hiçbir şey olma fırsatı bulamadan 'kayıp bir gün' altyazısıyla gelebilir. Yansıtmayı fark etmek gerçeği değiştirmez; amacı da bu değildir. Sana yalnızca altyazının projektörden geldiğini hatırlatır — ve altyazılar, gerçeklerin aksine, yeniden yazılabilir.",ru:"«Ум — проектор» — это способ смотреть, метафора, а не механизм. Между миром и вами ум добавляет слой: воспоминания, настроения, прогнозы. Медленное утро может прийти уже с подписью «потерянный день», не успев стать вообще ничем. Заметить проекцию — не значит изменить реальность, и не для этого это нужно. Это просто напоминает: подпись пришла из проектора, а подписи, в отличие от фактов, можно переписать.",vi:"'Tâm trí là máy chiếu' là một cách nhìn — một ẩn dụ, không phải một cơ chế. Giữa thế giới và bạn, tâm trí thêm vào một lớp: ký ức, tâm trạng, dự đoán. Một buổi sáng chậm chạp có thể đến với dòng chú thích 'một ngày bỏ đi' trước cả khi nó kịp trở thành gì. Nhận ra sự phóng chiếu không làm thay đổi điều có thật, và cũng không nhằm làm vậy. Nó chỉ nhắc bạn rằng dòng chú thích đến từ máy chiếu — và chú thích, khác với sự thật, có thể viết lại.",ar:"'العقل جهاز عرض' طريقةٌ في النظر — استعارة لا آلية. بين العالم وبينك يضيف العقل طبقة: ذكريات، أمزجة، توقّعات. قد يصل صباحٌ بطيء وقد كُتب عليه سلفًا 'يوم ضائع' قبل أن تتاح له فرصة أن يكون أي شيء. رصدُ الإسقاط لا يغيّر ما هو واقعي، وليس المقصود منه ذلك. إنه فقط يذكّرك بأن التعليق جاء من جهاز العرض — والتعليقات، بخلاف الوقائع، يمكن إعادة كتابتها."},"Catch the caption":{es:"Caza el rótulo",ca:"Caça el rètol",fr:"Attraper la légende",de:"Fang die Bildunterschrift",it:"Cogli la didascalia",pt:"Apanha a legenda",zh:"捕捉字幕",ja:"字幕をつかまえる",ko:"자막 잡아내기",hi:"कैप्शन पकड़ें",id:"Tangkap keterangannya",tr:"Altyazıyı yakala",ru:"Поймать подпись",vi:"Bắt lấy dòng chú thích",ar:"التقط التعليق"},"Pick a moment from today that already carries a label — 'ruined', 'wasted', 'typical'.":{es:"Elige un momento de hoy que ya lleve etiqueta: 'arruinado', 'desperdiciado', 'típico'.",ca:"Tria un moment d'avui que ja porti etiqueta: 'arruïnat', 'malgastat', 'típic'.",fr:"Choisissez un moment d'aujourd'hui qui porte déjà une étiquette — « fichu », « gâché », « typique ».",de:"Wähle einen Moment von heute, der schon ein Etikett trägt — 'ruiniert', 'vergeudet', 'typisch'.",it:"Scegli un momento di oggi che porta già un'etichetta: 'rovinato', 'sprecato', 'tipico'.",pt:"Escolhe um momento de hoje que já traga um rótulo — 'estragado', 'desperdiçado', 'típico'.",zh:"挑一个今天已经被贴上标签的时刻——“毁了”“浪费了”“老样子”。",ja:"今日のなかから、すでにラベルのついた瞬間を選びます。「台無し」「無駄」「いつものこと」。",ko:"오늘 중 이미 딱지가 붙은 순간을 하나 고릅니다 — '망했다', '허비했다', '늘 그렇지'.",hi:"आज का कोई पल चुनें जिस पर पहले से लेबल लगा हो — 'बर्बाद', 'गँवाया', 'हमेशा जैसा'।",id:"Pilih satu momen hari ini yang sudah berlabel — 'kacau', 'terbuang', 'biasa lagi'.",tr:"Bugünden, üzerinde etiket taşıyan bir an seç — 'mahvoldu', 'boşa gitti', 'her zamanki gibi'.",ru:"Выберите момент сегодняшнего дня, на котором уже висит ярлык — «испорчено», «впустую», «как всегда».",vi:"Chọn một khoảnh khắc hôm nay đã mang sẵn nhãn — 'hỏng rồi', 'phí hoài', 'lại thế'.",ar:"اختر لحظة من اليوم تحمل وسمًا جاهزًا — 'خربت'، 'ضاعت'، 'كالعادة'."},"Separate the layers: what actually happened (what a camera would record), and the caption your mind added.":{es:"Separa las capas: lo que pasó de verdad (lo que grabaría una cámara) y el rótulo que añadió tu mente.",ca:"Separa les capes: el que va passar de debò (el que gravaria una càmera) i el rètol que hi va afegir la teva ment.",fr:"Séparez les couches : ce qui s'est réellement passé (ce qu'une caméra enregistrerait) et la légende ajoutée par votre esprit.",de:"Trenne die Schichten: was tatsächlich geschah (was eine Kamera aufnehmen würde) und die Unterschrift, die dein Geist hinzugefügt hat.",it:"Separa gli strati: ciò che è successo davvero (ciò che una telecamera registrerebbe) e la didascalia aggiunta dalla tua mente.",pt:"Separa as camadas: o que aconteceu de facto (o que uma câmara gravaria) e a legenda que a tua mente acrescentou.",zh:"把两层分开：实际发生的（摄像机会录下的），和你的心加上的字幕。",ja:"層を分けます。実際に起きたこと（カメラが記録するもの）と、心がつけた字幕。",ko:"층을 나눠 봅니다. 실제로 일어난 일(카메라가 찍었을 것)과 마음이 덧붙인 자막.",hi:"परतें अलग करें: जो सचमुच हुआ (जो कैमरा रिकॉर्ड करता) और जो कैप्शन आपके मन ने जोड़ा।",id:"Pisahkan lapisannya: yang benar-benar terjadi (yang akan direkam kamera), dan keterangan yang ditambahkan pikiranmu.",tr:"Katmanları ayır: gerçekte olan (bir kameranın kaydedeceği) ve zihninin eklediği altyazı.",ru:"Разделите слои: что произошло на самом деле (что записала бы камера) и подпись, которую добавил ум.",vi:"Tách các lớp ra: điều thực sự xảy ra (điều máy quay sẽ ghi lại) và dòng chú thích tâm trí bạn thêm vào.",ar:"افصل الطبقات: ما حدث فعلًا (ما كانت الكاميرا ستسجّله)، والتعليق الذي أضافه عقلك."},"Say the caption with 'my mind is showing me…' in front of it. Just that — no arguing with it.":{es:"Di el rótulo con 'mi mente me está mostrando…' delante. Solo eso — sin discutir con él.",ca:"Digues el rètol amb 'la meva ment m'està mostrant…' al davant. Només això — sense discutir-hi.",fr:"Dites la légende en la faisant précéder de « mon esprit me montre… ». C'est tout — sans discuter avec elle.",de:"Sprich die Unterschrift mit 'mein Geist zeigt mir…' davor. Nur das — ohne mit ihr zu streiten.",it:"Pronuncia la didascalia con davanti 'la mia mente mi sta mostrando…'. Solo questo — senza discuterci.",pt:"Diz a legenda com 'a minha mente está a mostrar-me…' à frente. Só isso — sem discutir com ela.",zh:"把字幕念出来，前面加上“我的心正在给我放映……”。仅此而已——不必与它争辩。",ja:"字幕の前に「私の心はいま、こう映している……」とつけて言います。それだけ。言い争いはしません。",ko:"자막 앞에 '내 마음이 지금 보여주는 건…'을 붙여 말해 봅니다. 그뿐입니다 — 자막과 다투지 않습니다.",hi:"कैप्शन के आगे 'मेरा मन मुझे दिखा रहा है…' लगाकर कहें। बस इतना — उससे बहस नहीं।",id:"Ucapkan keterangan itu dengan awalan 'pikiranku sedang menayangkan…'. Itu saja — tanpa berdebat dengannya.",tr:"Altyazıyı başına 'zihnim bana şunu gösteriyor…' ekleyerek söyle. Sadece bu — onunla tartışma.",ru:"Произнесите подпись, добавив перед ней «мой ум показывает мне…». Только это — не споря с ней.",vi:"Nói dòng chú thích với câu 'tâm trí tôi đang chiếu cho tôi…' ở phía trước. Chỉ vậy thôi — không tranh cãi với nó.",ar:"قل التعليق مسبوقًا بعبارة 'عقلي يعرض عليّ…'. هذا فقط — من دون جدال معه."},"Now write one alternative caption a kind narrator might use. You don't have to believe it; you're only proving the projector holds more than one reel.":{es:"Ahora escribe un rótulo alternativo que usaría un narrador amable. No hace falta creérselo; solo estás demostrando que el proyector tiene más de una bobina.",ca:"Ara escriu un rètol alternatiu que faria servir un narrador amable. No cal creure-se'l; només estàs demostrant que el projector té més d'una bobina.",fr:"Écrivez maintenant une légende alternative qu'un narrateur bienveillant utiliserait. Pas besoin d'y croire ; vous prouvez seulement que le projecteur a plus d'une bobine.",de:"Schreibe nun eine alternative Unterschrift, die ein freundlicher Erzähler verwenden würde. Du musst sie nicht glauben; du beweist nur, dass der Projektor mehr als eine Filmrolle hat.",it:"Ora scrivi una didascalia alternativa che userebbe un narratore gentile. Non devi crederci; stai solo dimostrando che il proiettore ha più di una bobina.",pt:"Agora escreve uma legenda alternativa que um narrador bondoso usaria. Não precisas de acreditar nela; estás apenas a provar que o projetor tem mais do que uma bobina.",zh:"现在写一条善意的旁白会用的替代字幕。不必相信它；你只是在证明放映机不止一卷胶片。",ja:"今度は、やさしい語り手ならつけるであろう別の字幕を書きます。信じる必要はありません。映写機にリールが一本以上あると証明しているだけです。",ko:"이제 다정한 해설자라면 쓸 법한 다른 자막을 하나 적어 봅니다. 믿지 않아도 됩니다. 영사기에 필름이 한 롤만 있는 게 아니라는 걸 증명하는 것뿐이니까요.",hi:"अब एक वैकल्पिक कैप्शन लिखें जो कोई स्नेही सूत्रधार इस्तेमाल करता। उस पर यक़ीन ज़रूरी नहीं; आप बस साबित कर रहे हैं कि प्रोजेक्टर में एक से ज़्यादा रील हैं।",id:"Sekarang tulis satu keterangan alternatif yang mungkin dipakai narator yang baik hati. Tak perlu memercayainya; kamu hanya membuktikan proyektor itu punya lebih dari satu rol film.",tr:"Şimdi nazik bir anlatıcının kullanabileceği alternatif bir altyazı yaz. İnanman gerekmiyor; yalnızca projektörde birden fazla makara olduğunu kanıtlıyorsun.",ru:"Теперь напишите одну альтернативную подпись, которую использовал бы добрый рассказчик. Верить в неё не обязательно — вы лишь доказываете, что у проектора больше одной плёнки.",vi:"Giờ hãy viết một chú thích khác mà một người kể chuyện tử tế có thể dùng. Không cần phải tin nó; bạn chỉ đang chứng minh máy chiếu có nhiều hơn một cuộn phim.",ar:"الآن اكتب تعليقًا بديلًا قد يستخدمه راوٍ لطيف. لا يلزم أن تصدّقه؛ أنت فقط تثبت أن جهاز العرض يحمل أكثر من بكرة واحدة."},"Challenges are opportunities":{es:"Los desafíos son oportunidades",ca:"Els desafiaments són oportunitats",fr:"Les défis sont des opportunités",de:"Herausforderungen sind Chancen",it:"Le sfide sono opportunità",pt:"Os desafios são oportunidades",zh:"挑战是机会",ja:"困難は機会",ko:"도전은 기회",hi:"चुनौतियाँ अवसर हैं",id:"Tantangan adalah peluang",tr:"Zorluklar fırsattır",ru:"Трудности — это возможности",vi:"Thử thách là cơ hội",ar:"التحديات فرص"},"Some hard things leave something usable behind. Checking is optional.":{es:"Algunas cosas duras dejan algo aprovechable. Mirarlo es opcional.",ca:"Algunes coses dures deixen alguna cosa aprofitable. Mirar-ho és opcional.",fr:"Certaines épreuves laissent quelque chose d'utile derrière elles. Vérifier est facultatif.",de:"Manche harten Dinge lassen etwas Brauchbares zurück. Nachzusehen ist freiwillig.",it:"Alcune cose dure lasciano qualcosa di utilizzabile. Controllare è facoltativo.",pt:"Algumas coisas difíceis deixam algo aproveitável. Verificar é opcional.",zh:"有些难事会留下可用的东西。要不要去看，由你决定。",ja:"つらい出来事が、使えるものを残していくことがあります。確かめるかどうかは自由です。",ko:"어떤 힘든 일은 쓸 만한 것을 남깁니다. 확인은 선택입니다.",hi:"कुछ कठिन चीज़ें पीछे कुछ काम का छोड़ जाती हैं। देखना आपकी मर्ज़ी है।",id:"Beberapa hal berat meninggalkan sesuatu yang berguna. Memeriksanya tidak wajib.",tr:"Bazı zor şeyler geride işe yarar bir şey bırakır. Bakmak isteğe bağlı.",ru:"Некоторые тяжёлые вещи оставляют после себя что-то полезное. Проверять — по желанию.",vi:"Một số chuyện khó khăn để lại điều dùng được. Kiểm tra hay không là tùy bạn.",ar:"بعض الأمور الصعبة تترك خلفها شيئًا نافعًا. والتحقق من ذلك اختياري."},"'Every challenge is an opportunity' can sound like pressure — as if you owed the world a silver lining. This tool is smaller and more honest: some hard things, once they have happened anyway, leave something usable behind — a boundary you finally set, a skill you never wanted but now have, a person you'd never have met. Not all of them, and never on schedule. The practice is not to celebrate difficulty; it's to check, gently and on your own terms, whether this one left anything you can use.":{es:"'Todo desafío es una oportunidad' puede sonar a presión, como si le debieras al mundo un lado bueno. Esta herramienta es más pequeña y más honesta: algunas cosas duras, una vez que ya han pasado, dejan algo aprovechable — un límite que por fin pusiste, una habilidad que nunca quisiste pero ahora tienes, una persona que no habrías conocido. No todas, y nunca según calendario. La práctica no es celebrar la dificultad; es comprobar, con suavidad y en tus términos, si esta dejó algo que puedas usar.",ca:"'Tot desafiament és una oportunitat' pot sonar a pressió, com si deguessis al món un costat bo. Aquesta eina és més petita i més honesta: algunes coses dures, un cop ja han passat, deixen alguna cosa aprofitable — un límit que per fi vas posar, una habilitat que mai no vas voler però ara tens, una persona que no hauries conegut. No totes, i mai segons calendari. La pràctica no és celebrar la dificultat; és comprovar, amb suavitat i en els teus termes, si aquesta va deixar res que puguis fer servir.",fr:"« Chaque défi est une opportunité » peut sonner comme une pression — comme si vous deviez au monde un bon côté. Cet outil est plus petit et plus honnête : certaines épreuves, une fois qu'elles ont eu lieu de toute façon, laissent quelque chose d'utile — une limite enfin posée, une compétence jamais voulue mais désormais acquise, une personne que vous n'auriez jamais rencontrée. Pas toutes, et jamais à date fixe. La pratique n'est pas de célébrer la difficulté ; c'est de vérifier, doucement et à vos conditions, si celle-ci a laissé quelque chose d'utilisable.",de:"'Jede Herausforderung ist eine Chance' kann wie Druck klingen — als schuldest du der Welt einen Silberstreif. Dieses Werkzeug ist kleiner und ehrlicher: Manche harten Dinge lassen, wenn sie ohnehin geschehen sind, etwas Brauchbares zurück — eine Grenze, die du endlich gezogen hast, eine Fähigkeit, die du nie wolltest und nun hast, einen Menschen, den du nie getroffen hättest. Nicht alle, und nie nach Plan. Die Übung besteht nicht darin, Schwierigkeiten zu feiern, sondern sanft und zu deinen Bedingungen nachzusehen, ob diese hier etwas Brauchbares hinterlassen hat.",it:"'Ogni sfida è un'opportunità' può suonare come una pressione, come se dovessi al mondo un lato positivo. Questo strumento è più piccolo e più onesto: alcune cose dure, una volta che ormai sono accadute, lasciano qualcosa di utilizzabile — un limite che finalmente hai posto, un'abilità che non volevi ma ora possiedi, una persona che non avresti mai incontrato. Non tutte, e mai nei tempi previsti. La pratica non è celebrare la difficoltà; è controllare, con dolcezza e alle tue condizioni, se questa ha lasciato qualcosa che puoi usare.",pt:"'Cada desafio é uma oportunidade' pode soar a pressão — como se devesses ao mundo um lado bom. Esta ferramenta é mais pequena e mais honesta: algumas coisas difíceis, depois de já terem acontecido, deixam algo aproveitável — um limite que finalmente puseste, uma competência que nunca quiseste mas agora tens, uma pessoa que nunca terias conhecido. Nem todas, e nunca dentro do prazo. A prática não é celebrar a dificuldade; é verificar, com calma e nos teus termos, se esta deixou algo que possas usar.",zh:"“每个挑战都是机会”听起来可能像一种压力——好像你欠这个世界一个好的一面。这个工具更小、也更诚实：有些难事，既然已经发生了，会留下可用的东西——一条你终于划下的界线、一项你从没想要却已拥有的本领、一个你本不会遇见的人。不是所有难事都这样，也从不按时间表。这个练习不是庆祝困难，而是温和地、按你自己的节奏，看看这一件是否留下了你能用的东西。",ja:"「すべての困難は機会だ」という言葉は、時にプレッシャーに聞こえます。まるで世界に対して、良い面を見つける義務があるかのように。このツールはもっと小さく、もっと正直です。つらい出来事のいくつかは、どのみち起きてしまった後に、使えるものを残していきます。ようやく引けた境界線、望まなかったのに身についた力、出会うはずのなかった人。全部ではないし、予定どおりでもありません。練習は困難を讃えることではなく、これが何か使えるものを残したかどうかを、やさしく、自分のペースで確かめることです。",ko:"'모든 도전은 기회다'라는 말은 압박처럼 들릴 수 있습니다 — 마치 세상에 좋은 면을 빚진 것처럼요. 이 도구는 더 작고 더 정직합니다. 어떤 힘든 일은, 이미 일어나 버린 뒤에, 쓸 만한 것을 남깁니다 — 마침내 그은 경계선, 원한 적 없지만 이제 갖게 된 기술, 아니었으면 만나지 못했을 사람. 전부는 아니고, 정해진 때에 오지도 않습니다. 이 연습은 어려움을 축하하는 것이 아니라, 부드럽게, 당신의 방식대로, 이번 일이 쓸 만한 것을 남겼는지 확인해 보는 것입니다.",hi:"'हर चुनौती एक अवसर है' दबाव जैसा लग सकता है — मानो आप दुनिया के क़र्ज़दार हों कि हर चीज़ का उजला पहलू ढूँढ़ें। यह उपकरण छोटा और ज़्यादा ईमानदार है: कुछ कठिन चीज़ें, जब हो ही चुकी हों, पीछे कुछ काम का छोड़ जाती हैं — एक सीमा जो आपने आख़िरकार खींची, एक हुनर जो आप कभी नहीं चाहते थे पर अब है, एक इंसान जिससे आप कभी न मिलते। सब नहीं, और कभी तय समय पर नहीं। अभ्यास कठिनाई का जश्न मनाना नहीं है; धीरे से, अपनी शर्तों पर, यह देखना है कि क्या इसने कुछ ऐसा छोड़ा जो आपके काम आए।",id:"'Setiap tantangan adalah peluang' bisa terdengar seperti tekanan — seolah kamu berutang sisi baik kepada dunia. Alat ini lebih kecil dan lebih jujur: beberapa hal berat, setelah toh sudah terjadi, meninggalkan sesuatu yang berguna — batas yang akhirnya kamu tegakkan, keterampilan yang tak pernah kamu inginkan tapi kini kamu miliki, seseorang yang tak akan pernah kamu temui. Tidak semuanya, dan tak pernah sesuai jadwal. Latihannya bukan merayakan kesulitan; melainkan memeriksa, dengan lembut dan menurut caramu sendiri, apakah yang satu ini meninggalkan sesuatu yang bisa kamu pakai.",tr:"'Her zorluk bir fırsattır' sözü baskı gibi gelebilir — sanki dünyaya bir gümüş astar borçluymuşsun gibi. Bu araç daha küçük ve daha dürüst: Bazı zor şeyler, nasılsa yaşandıktan sonra, geride işe yarar bir şey bırakır — sonunda koyduğun bir sınır, hiç istemediğin ama artık sahip olduğun bir beceri, yoksa asla tanışamayacağın bir insan. Hepsi değil ve asla takvime göre değil. Uygulama zorluğu kutlamak değil; nazikçe ve kendi şartlarınla, bunun kullanabileceğin bir şey bırakıp bırakmadığına bakmaktır.",ru:"«Каждая трудность — это возможность» может звучать как давление, будто вы должны миру светлую сторону. Этот инструмент меньше и честнее: некоторые тяжёлые вещи, раз уж они всё равно случились, оставляют после себя что-то полезное — границу, которую вы наконец провели, умение, которого не хотели, но теперь имеете, человека, которого иначе не встретили бы. Не все и никогда по расписанию. Практика не в том, чтобы праздновать трудности, а в том, чтобы мягко и на своих условиях проверить: не оставила ли эта после себя что-то, чем можно воспользоваться.",vi:"'Mọi thử thách đều là cơ hội' có thể nghe như một áp lực — như thể bạn nợ thế giới một mặt tích cực. Công cụ này nhỏ hơn và thật hơn: một số chuyện khó khăn, khi dù sao cũng đã xảy ra, để lại điều dùng được — một ranh giới cuối cùng bạn đã đặt, một kỹ năng bạn chưa từng muốn nhưng giờ đã có, một người mà lẽ ra bạn không bao giờ gặp. Không phải tất cả, và không bao giờ đúng hẹn. Bài thực hành không phải là ăn mừng khó khăn; mà là kiểm tra, nhẹ nhàng và theo cách của bạn, xem chuyện này có để lại gì bạn dùng được không.",ar:"'كل تحدٍّ فرصة' قد تبدو عبارةً ضاغطة — كأنك مدينٌ للعالم بجانبٍ مشرق. هذه الأداة أصغر وأصدق: بعض الأمور الصعبة، بعد أن تكون قد حدثت على أي حال، تترك خلفها شيئًا نافعًا — حدًّا وضعتَه أخيرًا، مهارةً لم تُردها يومًا لكنها صارت لك، إنسانًا ما كنت لتلقاه. ليس كلها، وليس أبدًا في موعد محدد. الممارسة ليست الاحتفاء بالصعوبة؛ بل التحقق بلطف، ووفق شروطك أنت، مما إذا كانت هذه قد تركت شيئًا يمكنك استعماله."},"The salvage check":{es:"La revisión de rescate",ca:"La revisió de rescat",fr:"Le contrôle de récupération",de:"Die Bergungsprüfung",it:"Il controllo di recupero",pt:"A verificação de salvados",zh:"打捞清点",ja:"引き揚げチェック",ko:"건져내기 점검",hi:"बचत-जाँच",id:"Pemeriksaan sisa berharga",tr:"Kurtarma kontrolü",ru:"Проверка на уцелевшее",vi:"Cuộc kiểm kê vớt vát",ar:"فحص ما يُنتشل"},"Choose one difficulty that is over or has gone quiet — not one you are in the middle of.":{es:"Elige una dificultad que haya terminado o se haya calmado — no una en la que estés en medio.",ca:"Tria una dificultat que hagi acabat o s'hagi calmat — no una en què estiguis al mig.",fr:"Choisissez une difficulté terminée ou apaisée — pas une que vous traversez en ce moment.",de:"Wähle eine Schwierigkeit, die vorbei oder still geworden ist — nicht eine, in der du gerade mittendrin steckst.",it:"Scegli una difficoltà che è finita o si è quietata — non una in cui sei nel mezzo.",pt:"Escolhe uma dificuldade que já passou ou acalmou — não uma em que estejas no meio.",zh:"选一件已经过去或已平息的难事——不要选正身处其中的。",ja:"終わったか、静かになった困難をひとつ選びます。いま渦中にあるものは選びません。",ko:"끝났거나 잠잠해진 어려움을 하나 고릅니다 — 한창 겪고 있는 것은 말고요.",hi:"कोई ऐसी मुश्किल चुनें जो बीत चुकी हो या शांत हो गई हो — वह नहीं जिसके बीच में आप अभी हों।",id:"Pilih satu kesulitan yang sudah berlalu atau mereda — bukan yang sedang kamu jalani.",tr:"Bitmiş ya da yatışmış bir zorluk seç — ortasında olduğun birini değil.",ru:"Выберите трудность, которая закончилась или утихла — не ту, в середине которой вы сейчас.",vi:"Chọn một khó khăn đã qua hoặc đã lắng xuống — không phải chuyện bạn đang ở giữa.",ar:"اختر صعوبةً انتهت أو هدأت — لا صعوبةً أنت في خضمّها الآن."},"Ask: did it leave anything usable behind? A skill, a limit you now respect, a person, a shortcut.":{es:"Pregunta: ¿dejó algo aprovechable? Una habilidad, un límite que ahora respetas, una persona, un atajo.",ca:"Pregunta: va deixar res aprofitable? Una habilitat, un límit que ara respectes, una persona, una drecera.",fr:"Demandez : a-t-elle laissé quelque chose d'utile ? Une compétence, une limite désormais respectée, une personne, un raccourci.",de:"Frage: Hat sie etwas Brauchbares hinterlassen? Eine Fähigkeit, eine Grenze, die du jetzt achtest, einen Menschen, eine Abkürzung.",it:"Chiedi: ha lasciato qualcosa di utilizzabile? Un'abilità, un limite che ora rispetti, una persona, una scorciatoia.",pt:"Pergunta: deixou algo aproveitável? Uma competência, um limite que agora respeitas, uma pessoa, um atalho.",zh:"问：它留下了什么可用的吗？一项本领、一条你如今尊重的界线、一个人、一条捷径。",ja:"問いかけます。何か使えるものを残しただろうか。技術、いま大切にしている限度、人、近道。",ko:"물어봅니다. 쓸 만한 것을 남겼나요? 기술 하나, 이제는 지키는 한계선, 사람, 지름길.",hi:"पूछें: क्या वह कुछ काम का छोड़ गई? कोई हुनर, कोई सीमा जिसका अब आप सम्मान करते हैं, कोई इंसान, कोई छोटा रास्ता।",id:"Tanyakan: apakah ia meninggalkan sesuatu yang berguna? Sebuah keterampilan, batas yang kini kamu hormati, seseorang, jalan pintas.",tr:"Sor: geride işe yarar bir şey bıraktı mı? Bir beceri, artık saygı duyduğun bir sınır, bir insan, bir kestirme.",ru:"Спросите: осталось ли после неё что-то полезное? Умение, граница, которую вы теперь уважаете, человек, короткий путь.",vi:"Hỏi: nó có để lại gì dùng được không? Một kỹ năng, một giới hạn giờ bạn tôn trọng, một người, một lối tắt.",ar:"اسأل: هل تركت خلفها شيئًا نافعًا؟ مهارة، حدًّا صرتَ تحترمه، إنسانًا، طريقًا مختصرة."},"If the honest answer is 'nothing', write that down too. Some things are just hard. That answer counts.":{es:"Si la respuesta honesta es 'nada', escríbelo también. Algunas cosas simplemente son duras. Esa respuesta cuenta.",ca:"Si la resposta honesta és 'res', escriu-ho també. Algunes coses simplement són dures. Aquesta resposta compta.",fr:"Si la réponse honnête est « rien », écrivez-le aussi. Certaines choses sont juste dures. Cette réponse compte.",de:"Wenn die ehrliche Antwort 'nichts' lautet, schreibe auch das auf. Manche Dinge sind einfach schwer. Diese Antwort zählt.",it:"Se la risposta onesta è 'niente', scrivi anche quello. Alcune cose sono semplicemente dure. Quella risposta conta.",pt:"Se a resposta honesta for 'nada', escreve isso também. Algumas coisas são simplesmente difíceis. Essa resposta conta.",zh:"如果诚实的答案是“什么都没有”，也写下来。有些事就是难。这个答案同样算数。",ja:"正直な答えが「何もない」なら、それも書きます。ただつらいだけのこともあります。その答えも立派に数に入ります。",ko:"정직한 답이 '아무것도 없다'라면 그것도 적어 두세요. 어떤 일은 그냥 힘든 일입니다. 그 답도 유효합니다.",hi:"अगर ईमानदार जवाब 'कुछ नहीं' है, तो वह भी लिख लें। कुछ चीज़ें बस कठिन होती हैं। वह जवाब भी मायने रखता है।",id:"Jika jawaban jujurnya 'tidak ada', tulis juga itu. Beberapa hal memang sekadar berat. Jawaban itu tetap berarti.",tr:"Dürüst cevap 'hiçbir şey' ise, onu da yaz. Bazı şeyler sadece zordur. O cevap da sayılır.",ru:"Если честный ответ — «ничего», запишите и это. Некоторые вещи просто тяжелы. Такой ответ тоже считается.",vi:"Nếu câu trả lời thành thật là 'không có gì', hãy ghi lại điều đó. Có những chuyện chỉ đơn giản là khó. Câu trả lời ấy vẫn được tính.",ar:"إن كان الجواب الصادق 'لا شيء'، فاكتب ذلك أيضًا. بعض الأمور صعبة فحسب. وهذا الجواب له قيمته."},"If you found something, name where it could serve you next. That's the whole exercise — salvage, never gratitude on command.":{es:"Si encontraste algo, nombra dónde podría servirte la próxima vez. Ese es todo el ejercicio — rescate, nunca gratitud por obligación.",ca:"Si vas trobar alguna cosa, anomena on et podria servir la pròxima vegada. Aquest és tot l'exercici — rescat, mai gratitud per obligació.",fr:"Si vous avez trouvé quelque chose, nommez où cela pourrait vous servir ensuite. C'est tout l'exercice — de la récupération, jamais de la gratitude sur commande.",de:"Wenn du etwas gefunden hast, benenne, wo es dir als Nächstes dienen könnte. Das ist die ganze Übung — Bergung, nie Dankbarkeit auf Befehl.",it:"Se hai trovato qualcosa, indica dove potrebbe servirti la prossima volta. È tutto qui l'esercizio — recupero, mai gratitudine a comando.",pt:"Se encontraste algo, diz onde te poderá servir a seguir. É esse todo o exercício — salvamento, nunca gratidão por obrigação.",zh:"如果找到了什么，说说它下次能在哪儿帮到你。练习到此为止——是打捞，从不是被要求的感恩。",ja:"見つかったなら、それが次にどこで役立ちそうかを言ってみます。練習はそれで全部。引き揚げであって、強制された感謝ではありません。",ko:"무언가 찾았다면, 다음에 어디서 쓰일지 이름 붙여 보세요. 그게 연습의 전부입니다 — 건져내기일 뿐, 명령받은 감사가 아닙니다.",hi:"अगर कुछ मिला, तो बताएं कि वह अगली बार कहाँ काम आ सकता है। बस यही पूरा अभ्यास है — बचाव, हुक्म पर कृतज्ञता कभी नहीं।",id:"Jika kamu menemukan sesuatu, sebutkan di mana ia bisa berguna nanti. Itulah seluruh latihannya — menyelamatkan yang tersisa, bukan bersyukur karena disuruh.",tr:"Bir şey bulduysan, bir dahaki sefere nerede işine yarayabileceğini söyle. Bütün egzersiz bu — kurtarma, asla emirle şükran değil.",ru:"Если что-то нашлось, назовите, где это может пригодиться дальше. В этом всё упражнение — спасение уцелевшего, а не благодарность по команде.",vi:"Nếu tìm thấy điều gì, hãy gọi tên nơi nó có thể giúp bạn lần tới. Đó là toàn bộ bài tập — vớt vát, không bao giờ là biết ơn theo mệnh lệnh.",ar:"إن وجدتَ شيئًا، فسمِّ أين قد يخدمك لاحقًا. هذا هو التمرين كله — انتشالٌ، لا امتنانٌ بالأمر أبدًا."},"Clear identity, clear goal":{es:"Identidad clara, objetivo claro",ca:"Identitat clara, objectiu clar",fr:"Identité claire, objectif clair",de:"Klare Identität, klares Ziel",it:"Identità chiara, obiettivo chiaro",pt:"Identidade clara, objetivo claro",zh:"身份清晰，目标清晰",ja:"明確なアイデンティティ、明確な目標",ko:"명확한 정체성, 명확한 목표",hi:"साफ़ पहचान, साफ़ लक्ष्य",id:"Identitas jelas, tujuan jelas",tr:"Net kimlik, net hedef",ru:"Ясная идентичность — ясная цель",vi:"Bản sắc rõ, mục tiêu rõ",ar:"هوية واضحة، هدف واضح"},"Knowing who you're being makes the small choices lighter.":{es:"Saber quién estás siendo aligera las pequeñas decisiones.",ca:"Saber qui estàs sent alleugereix les petites decisions.",fr:"Savoir qui l'on est rend les petits choix plus légers.",de:"Zu wissen, wer du gerade bist, macht die kleinen Entscheidungen leichter.",it:"Sapere chi stai essendo alleggerisce le piccole scelte.",pt:"Saber quem estás a ser torna as pequenas escolhas mais leves.",zh:"知道自己在做怎样的人，小选择就变轻了。",ja:"自分がどういう人でいるかを知っていると、小さな選択が軽くなります。",ko:"내가 어떤 사람으로 살고 있는지 알면 작은 선택들이 가벼워집니다.",hi:"आप कौन बन रहे हैं यह जानना छोटे फ़ैसलों को हल्का कर देता है।",id:"Tahu sedang menjadi siapa membuat pilihan-pilihan kecil terasa ringan.",tr:"Kim olduğunu bilmek küçük seçimleri hafifletir.",ru:"Знание, кем вы являетесь, делает мелкие решения легче.",vi:"Biết mình đang là ai khiến những lựa chọn nhỏ nhẹ nhàng hơn.",ar:"أن تعرف مَن تكون يجعل الخيارات الصغيرة أخفّ."},"A goal tells you what to do; an identity tells you who is doing it. 'I want to read more' is a wish — 'I'm a reader' quietly reorganises small choices without a fight. And identity, unlike a schedule, travels well: even on days when your body decides most of the plan, you still choose the adjective — someone careful with themselves, someone who keeps promises small and keeps them. A clear identity makes goals lighter, because you stop renegotiating with yourself at every step.":{es:"Un objetivo te dice qué hacer; una identidad te dice quién lo hace. 'Quiero leer más' es un deseo — 'soy lector' reorganiza en silencio las pequeñas decisiones sin pelea. Y la identidad, a diferencia de un horario, viaja bien: incluso los días en que tu cuerpo decide casi todo el plan, tú sigues eligiendo el adjetivo — alguien cuidadoso consigo mismo, alguien que hace promesas pequeñas y las cumple. Una identidad clara aligera los objetivos, porque dejas de renegociar contigo a cada paso.",ca:"Un objectiu et diu què fer; una identitat et diu qui ho fa. 'Vull llegir més' és un desig — 'soc lector' reorganitza en silenci les petites decisions sense baralla. I la identitat, a diferència d'un horari, viatja bé: fins i tot els dies en què el teu cos decideix gairebé tot el pla, tu segueixes triant l'adjectiu — algú curós amb si mateix, algú que fa promeses petites i les compleix. Una identitat clara alleugereix els objectius, perquè deixes de renegociar amb tu mateix a cada pas.",fr:"Un objectif vous dit quoi faire ; une identité vous dit qui le fait. « Je veux lire plus » est un souhait — « je suis un lecteur » réorganise en silence les petits choix, sans lutte. Et l'identité, contrairement à un emploi du temps, voyage bien : même les jours où votre corps décide de l'essentiel du programme, vous choisissez encore l'adjectif — quelqu'un de soigneux avec soi, quelqu'un qui fait des promesses petites et les tient. Une identité claire allège les objectifs, parce que vous cessez de renégocier avec vous-même à chaque pas.",de:"Ein Ziel sagt dir, was zu tun ist; eine Identität sagt dir, wer es tut. 'Ich will mehr lesen' ist ein Wunsch — 'ich bin ein Leser' ordnet kleine Entscheidungen still neu, ohne Kampf. Und Identität reist, anders als ein Zeitplan, gut: Selbst an Tagen, an denen dein Körper den Großteil des Plans bestimmt, wählst du noch das Adjektiv — jemand, der achtsam mit sich umgeht, jemand, der Versprechen klein hält und hält. Eine klare Identität macht Ziele leichter, weil du aufhörst, bei jedem Schritt mit dir selbst neu zu verhandeln.",it:"Un obiettivo ti dice cosa fare; un'identità ti dice chi lo fa. 'Voglio leggere di più' è un desiderio — 'sono un lettore' riorganizza in silenzio le piccole scelte senza lottare. E l'identità, a differenza di un orario, viaggia bene: anche nei giorni in cui il corpo decide gran parte del piano, l'aggettivo lo scegli ancora tu — qualcuno che ha cura di sé, qualcuno che fa promesse piccole e le mantiene. Un'identità chiara alleggerisce gli obiettivi, perché smetti di rinegoziare con te stesso a ogni passo.",pt:"Um objetivo diz-te o que fazer; uma identidade diz-te quem o faz. 'Quero ler mais' é um desejo — 'sou um leitor' reorganiza em silêncio as pequenas escolhas, sem luta. E a identidade, ao contrário de um horário, viaja bem: mesmo nos dias em que o corpo decide a maior parte do plano, continuas a escolher o adjetivo — alguém cuidadoso consigo, alguém que faz promessas pequenas e as cumpre. Uma identidade clara torna os objetivos mais leves, porque deixas de renegociar contigo a cada passo.",zh:"目标告诉你做什么；身份告诉你是谁在做。“我想多读书”是愿望——“我是个读书的人”则悄悄地重新安排小选择，不用较劲。而身份不像日程表，它随身携带：即使在身体决定大半计划的日子里，形容词仍由你选——一个善待自己的人，一个把承诺定得小并且守住的人。身份清晰了，目标就轻了，因为你不再每走一步都和自己重新谈判。",ja:"目標は「何をするか」を、アイデンティティは「誰がするか」を教えてくれます。「もっと読みたい」は願望ですが、「私は読む人だ」は小さな選択を静かに、争わずに並べ替えます。そしてアイデンティティは予定表と違って持ち運べます。体が予定の大半を決める日でも、形容詞はあなたが選べます。自分を丁寧に扱う人、約束を小さくして守る人。アイデンティティが明確だと目標は軽くなります。一歩ごとに自分と再交渉しなくてよくなるからです。",ko:"목표는 무엇을 할지 알려주고, 정체성은 누가 하는지 알려줍니다. '더 읽고 싶다'는 바람이지만 — '나는 읽는 사람'은 작은 선택들을 다툼 없이 조용히 재배열합니다. 그리고 정체성은 일정표와 달리 어디든 함께 갑니다. 몸이 계획의 대부분을 정하는 날에도 형용사는 여전히 당신이 고릅니다 — 자신을 조심스럽게 대하는 사람, 약속을 작게 하고 지키는 사람. 정체성이 명확하면 목표가 가벼워집니다. 걸음마다 자신과 재협상하기를 멈추게 되니까요.",hi:"लक्ष्य बताता है क्या करना है; पहचान बताती है कौन कर रहा है। 'मैं ज़्यादा पढ़ना चाहता हूँ' एक इच्छा है — 'मैं पढ़ने वाला इंसान हूँ' छोटे फ़ैसलों को चुपचाप, बिना संघर्ष के सँवार देता है। और पहचान, समय-सारणी के उलट, साथ चलती है: जिन दिनों शरीर ज़्यादातर योजना तय करता है, विशेषण तब भी आप चुनते हैं — कोई जो खुद के साथ नरमी रखता है, कोई जो वादे छोटे रखता है और निभाता है। साफ़ पहचान लक्ष्यों को हल्का कर देती है, क्योंकि आप हर क़दम पर खुद से दोबारा मोल-भाव करना छोड़ देते हैं।",id:"Tujuan memberitahumu apa yang harus dilakukan; identitas memberitahumu siapa yang melakukannya. 'Aku ingin membaca lebih banyak' adalah harapan — 'aku seorang pembaca' diam-diam menata ulang pilihan-pilihan kecil tanpa perlawanan. Dan identitas, tak seperti jadwal, mudah dibawa: bahkan di hari ketika tubuh menentukan sebagian besar rencana, kata sifatnya tetap kamu yang memilih — seseorang yang berhati-hati pada dirinya, seseorang yang membuat janji kecil dan menepatinya. Identitas yang jelas membuat tujuan lebih ringan, karena kamu berhenti bernegosiasi ulang dengan dirimu di tiap langkah.",tr:"Hedef sana ne yapacağını söyler; kimlik, bunu kimin yaptığını. 'Daha çok okumak istiyorum' bir dilektir — 'ben bir okurum' ise küçük seçimleri kavga etmeden sessizce yeniden düzenler. Ve kimlik, bir programın aksine, yanında taşınır: Bedenin planın çoğunu belirlediği günlerde bile sıfatı yine sen seçersin — kendine özenli biri, sözlerini küçük tutup tutan biri. Net bir kimlik hedefleri hafifletir; çünkü her adımda kendinle yeniden pazarlık etmeyi bırakırsın.",ru:"Цель говорит, что делать; идентичность — кто это делает. «Хочу больше читать» — это желание, а «я читатель» тихо перестраивает мелкие решения без борьбы. И идентичность, в отличие от расписания, всегда с вами: даже в дни, когда тело решает большую часть плана, прилагательное всё равно выбираете вы — человек, бережный к себе; человек, который даёт маленькие обещания и держит их. Ясная идентичность делает цели легче, потому что вы перестаёте на каждом шагу заново договариваться с собой.",vi:"Mục tiêu cho bạn biết phải làm gì; bản sắc cho bạn biết ai đang làm. 'Tôi muốn đọc nhiều hơn' là một mong ước — 'tôi là người đọc sách' lặng lẽ sắp xếp lại những lựa chọn nhỏ mà không cần tranh đấu. Và bản sắc, khác với thời gian biểu, luôn mang theo được: ngay cả những ngày cơ thể quyết định phần lớn kế hoạch, bạn vẫn chọn tính từ — một người cẩn thận với chính mình, một người hứa những điều nhỏ và giữ lời. Bản sắc rõ ràng khiến mục tiêu nhẹ hơn, vì bạn thôi phải thương lượng lại với mình ở từng bước.",ar:"الهدف يخبرك ماذا تفعل؛ والهوية تخبرك مَن الذي يفعل. 'أريد أن أقرأ أكثر' أمنية — أما 'أنا قارئ' فيعيد ترتيب الخيارات الصغيرة بهدوء ومن دون صراع. والهوية، بخلاف الجدول، تسافر معك: حتى في الأيام التي يقرر فيها جسدك معظم الخطة، تبقى أنت من يختار الصفة — شخصٌ رفيق بنفسه، شخصٌ يجعل وعوده صغيرة ويفي بها. الهوية الواضحة تجعل الأهداف أخف، لأنك تكفّ عن إعادة التفاوض مع نفسك عند كل خطوة."},"One sentence of identity":{es:"Una frase de identidad",ca:"Una frase d'identitat",fr:"Une phrase d'identité",de:"Ein Satz Identität",it:"Una frase di identità",pt:"Uma frase de identidade",zh:"一句身份宣言",ja:"アイデンティティの一文",ko:"정체성 한 문장",hi:"पहचान का एक वाक्य",id:"Satu kalimat identitas",tr:"Tek cümlelik kimlik",ru:"Одно предложение идентичности",vi:"Một câu về bản sắc",ar:"جملة هوية واحدة"},"Complete, in writing: 'I am the kind of person who…' — with something small and true, or almost true.":{es:"Completa por escrito: 'Soy el tipo de persona que…' — con algo pequeño y verdadero, o casi verdadero.",ca:"Completa per escrit: 'Soc el tipus de persona que…' — amb alguna cosa petita i veritable, o gairebé veritable.",fr:"Complétez par écrit : « Je suis le genre de personne qui… » — avec quelque chose de petit et de vrai, ou presque vrai.",de:"Vervollständige schriftlich: 'Ich bin die Art Mensch, die…' — mit etwas Kleinem und Wahrem, oder fast Wahrem.",it:"Completa per iscritto: 'Sono il tipo di persona che…' — con qualcosa di piccolo e vero, o quasi vero.",pt:"Completa por escrito: 'Sou o tipo de pessoa que…' — com algo pequeno e verdadeiro, ou quase verdadeiro.",zh:"写下并补全这句话：“我是那种……的人”——填一件小而真实、或接近真实的事。",ja:"書いて完成させます。「私は……する人だ」。小さくて本当のこと、またはほぼ本当のことで。",ko:"글로 완성해 봅니다. '나는 …하는 사람이다' — 작고 진실한 것, 혹은 거의 진실한 것으로요.",hi:"लिखकर पूरा करें: 'मैं ऐसा इंसान हूँ जो…' — किसी छोटी और सच्ची, या लगभग सच्ची बात से।",id:"Lengkapi secara tertulis: 'Aku tipe orang yang…' — dengan sesuatu yang kecil dan benar, atau hampir benar.",tr:"Yazarak tamamla: 'Ben … biriyim' — küçük ve doğru, ya da neredeyse doğru bir şeyle.",ru:"Допишите на бумаге: «Я из тех людей, кто…» — чем-то маленьким и правдивым или почти правдивым.",vi:"Viết và hoàn thành câu: 'Tôi là kiểu người…' — bằng điều gì đó nhỏ và đúng, hoặc gần đúng.",ar:"أكمل كتابةً: 'أنا من النوع الذي…' — بشيءٍ صغير وصادق، أو يكاد يكون صادقًا."},"Test it against a hard day: can you still be that person from the sofa? If not, shrink it until you can.":{es:"Ponla a prueba en un día duro: ¿puedes seguir siendo esa persona desde el sofá? Si no, encógela hasta que sí.",ca:"Posa-la a prova en un dia dur: pots continuar sent aquesta persona des del sofà? Si no, encongeix-la fins que sí.",fr:"Testez-la face à une journée difficile : pouvez-vous encore être cette personne depuis le canapé ? Sinon, réduisez-la jusqu'à ce que oui.",de:"Prüfe ihn an einem harten Tag: Kannst du dieser Mensch auch vom Sofa aus sein? Wenn nicht, verkleinere ihn, bis es geht.",it:"Mettila alla prova in una giornata dura: puoi essere ancora quella persona dal divano? Se no, rimpiccioliscila finché puoi.",pt:"Testa-a num dia difícil: consegues continuar a ser essa pessoa a partir do sofá? Se não, encolhe-a até conseguires.",zh:"拿一个难熬的日子来检验：躺在沙发上还能是那个人吗？不能的话，把句子缩小，直到可以。",ja:"つらい日で試します。ソファの上からでも、その人でいられますか。無理なら、いられる大きさまで縮めます。",ko:"힘든 날에 대 봅니다. 소파에서도 여전히 그 사람일 수 있나요? 아니라면, 될 때까지 문장을 줄입니다.",hi:"उसे किसी कठिन दिन पर परखें: क्या सोफ़े से भी आप वही इंसान रह सकते हैं? नहीं, तो उसे तब तक छोटा करें जब तक रह सकें।",id:"Uji dengan hari yang berat: masihkah kamu bisa menjadi orang itu dari sofa? Jika tidak, kecilkan sampai bisa.",tr:"Zor bir günle sına: koltuktan da o kişi olabiliyor musun? Olamıyorsan, olabilene kadar küçült.",ru:"Проверьте его тяжёлым днём: можете ли вы оставаться этим человеком, не вставая с дивана? Если нет — уменьшайте, пока не сможете.",vi:"Thử nó với một ngày khó khăn: bạn còn là người đó được không, ngay từ ghế sofa? Nếu không, thu nhỏ nó lại đến khi được.",ar:"اختبرها في يومٍ صعب: أيمكنك أن تظل ذلك الشخص من فوق الأريكة؟ إن لم يكن، فصغّرها حتى تستطيع."},"Find one action today, however small, that this person would take — and take only that.":{es:"Encuentra una acción hoy, por pequeña que sea, que esa persona haría — y haz solo esa.",ca:"Troba una acció avui, per petita que sigui, que aquesta persona faria — i fes només aquesta.",fr:"Trouvez une action aujourd'hui, aussi petite soit-elle, que cette personne ferait — et ne faites que celle-là.",de:"Finde heute eine Handlung, wie klein auch immer, die dieser Mensch tun würde — und tu nur diese.",it:"Trova un'azione oggi, per quanto piccola, che quella persona farebbe — e fai solo quella.",pt:"Encontra uma ação hoje, por pequena que seja, que essa pessoa faria — e faz apenas essa.",zh:"今天找一个那个人会做的行动，再小也行——只做这一个。",ja:"その人が取るであろう行動を、どんなに小さくてもいいので今日ひとつ見つけ、それだけをします。",ko:"그 사람이 할 법한 행동을 오늘 하나 찾습니다. 아무리 작아도 좋습니다 — 그리고 그것만 합니다.",hi:"आज एक काम खोजें, चाहे कितना भी छोटा हो, जो वह इंसान करता — और सिर्फ़ वही करें।",id:"Temukan satu tindakan hari ini, sekecil apa pun, yang akan dilakukan orang itu — dan lakukan hanya itu.",tr:"Bugün, o kişinin yapacağı bir eylem bul — ne kadar küçük olursa olsun — ve yalnızca onu yap.",ru:"Найдите сегодня одно действие, каким бы маленьким оно ни было, которое совершил бы этот человек, — и совершите только его.",vi:"Tìm một hành động hôm nay, dù nhỏ đến đâu, mà người đó sẽ làm — và chỉ làm điều đó.",ar:"جد اليوم فعلًا واحدًا، مهما صغُر، كان ذلك الشخص سيفعله — وافعله وحده."},"Repeat the sentence tomorrow morning. Identity is built from evidence, and one small proof a day is plenty.":{es:"Repite la frase mañana por la mañana. La identidad se construye con pruebas, y una pequeña prueba al día es más que suficiente.",ca:"Repeteix la frase demà al matí. La identitat es construeix amb proves, i una petita prova al dia és més que suficient.",fr:"Répétez la phrase demain matin. L'identité se construit sur des preuves, et une petite preuve par jour suffit largement.",de:"Wiederhole den Satz morgen früh. Identität baut sich aus Belegen, und ein kleiner Beweis pro Tag ist völlig genug.",it:"Ripeti la frase domani mattina. L'identità si costruisce con le prove, e una piccola prova al giorno è più che sufficiente.",pt:"Repete a frase amanhã de manhã. A identidade constrói-se com provas, e uma pequena prova por dia chega bem.",zh:"明天早上再念一遍这句话。身份是用证据砌成的，一天一个小小的证明就足够了。",ja:"明日の朝、その一文をもう一度唱えます。アイデンティティは証拠から築かれます。一日に小さな証明がひとつあれば十分です。",ko:"내일 아침 그 문장을 다시 말해 보세요. 정체성은 증거로 지어지고, 하루에 작은 증명 하나면 충분합니다.",hi:"कल सुबह वह वाक्य दोहराएँ। पहचान सबूतों से बनती है, और दिन में एक छोटा सबूत काफ़ी है।",id:"Ulangi kalimat itu besok pagi. Identitas dibangun dari bukti, dan satu bukti kecil sehari sudah cukup.",tr:"Cümleyi yarın sabah tekrar et. Kimlik kanıtlarla inşa edilir ve günde bir küçük kanıt fazlasıyla yeter.",ru:"Повторите предложение завтра утром. Идентичность строится из доказательств, и одного маленького в день вполне достаточно.",vi:"Lặp lại câu ấy sáng mai. Bản sắc được xây từ bằng chứng, và mỗi ngày một bằng chứng nhỏ là quá đủ.",ar:"كرّر الجملة صباح الغد. الهوية تُبنى من الأدلة، ودليلٌ صغير واحد في اليوم يكفي تمامًا."}};Object.keys(M).forEach(function(k){var cur=CF_UI_MAP[k]=CF_UI_MAP[k]||{};Object.keys(M[k]).forEach(function(l){if(cur[l]==null)cur[l]=M[k][l];});});})();
})();